\begin{aligned}
& \underset{\mathbf{x}\in{\mathbb R}^n}{\text{minimize}}
& & \|C\mathbf{x}-\mathbf{I}\|_2^2 \\
& \text{subject to}
& & \mathbf{x}_i\geq0,\ \forall i\in[n].
\end{aligned}

\begin{aligned}
& \underset{\mathbf{x}\in{\mathbb R}^n}{\text{minimize}}
& & \|A\mathbf{x}-\mathbf{b}\|_2^2 \\
& \text{subject to}
& & \mathbf{x}_i\geq0,\ \forall i\in[n].
\end{aligned}

Let $m,n\in{\mathbb{N}}$. Given $A\in{\mathbb R}^{m\times n}$ and $\mathbf{b}\in{\mathbb R}^m$ such that there exists a solution to $A\mathbf{x}=\mathbf{b}$. The goal of $\ell_1$ minimization is to solve the following optimization problem.
	\begin{equation*}
	\begin{aligned}
	& \underset{\mathbf{x}\in{\mathbb R}^n}{\text{minimize}}
	& & \|\mathbf{x}\|_1 \\
	& \text{subject to}
	& & A\mathbf{x}=\mathbf{b}.
	\end{aligned}
	\end{equation*}

\begin{aligned}
& \underset{\mathbf{x}\in{\mathbb R}^n}{\text{minimize}}
& & f(\mathbf{x}) \\
& \text{subject to}
& & g_i(\mathbf{x})\leq0,&\forall i=1,2,\dots m,\\
& & & h_j(\mathbf{x})=0,&\forall j=1,2,\dots,k,
\end{aligned}

Given the following two optimization programs where the strong duality holds and there exists feasible dual solution.\\
	\begin{minipage}{\linewidth}
		\begin{minipage}{0.5\linewidth}
			\begin{equation} \begin{aligned}
			& \underset{\mathbf{x}}{\text{minimize}}
			& & f(\mathbf{x}) \\
			& \text{subject to}
			& & g_i(\mathbf{x})\leq0,&\forall i=1,2,\dots,m,\\
			& & & h_j(\mathbf{x})=0,&\forall j=1,2,\dots,k.
			\end{aligned}
			\end{equation}
		\end{minipage}
		\begin{minipage}{0.5\linewidth}
			\begin{equation} \begin{aligned}
			& \underset{\mathbf{x}}{\text{minimize}}
			& & f(\mathbf{x}) \\
			& \text{subject to}
			& & g_i(\mathbf{x})\leq \mathbf{a}_i,&\forall i=1,2,\dots,m,\\
			& & & h_j(\mathbf{x})=\mathbf{b}_j,&\forall j=1,2,\dots,k.
			\end{aligned}
			\end{equation}
		\end{minipage}
	\end{minipage}

	\vspace{1em}

	Let $\mathbf{OPT}^{\text{original}}$ be the optimal value of the original program~\eqref{op:prelim perturbation-original} and $\mathbf{OPT}^{\text{perturbed}}$ be the optimal value of the perturbed program~\eqref{op:prelim perturbation-perturbed}. Let $(\mathbf{v}^*,\boldsymbol{\mu}^*)\in{\mathbb R}^m\times{\mathbb R}^k$ be the optimal dual solution of the perturbed program~\eqref{op:prelim perturbation-perturbed}. We have
	\begin{equation*}
	\mathbf{OPT}^{\text{original}}\geq\mathbf{OPT}^{\text{perturbed}}+\mathbf{a}^\top\mathbf{v}^*+\mathbf{b}^\top\boldsymbol{\mu}^*.
	\end{equation*}

\begin{aligned}
			& \underset{\mathbf{x}}{\text{minimize}}
			& & f(\mathbf{x}) \\
			& \text{subject to}
			& & g_i(\mathbf{x})\leq0,&\forall i=1,2,\dots,m,\\
			& & & h_j(\mathbf{x})=0,&\forall j=1,2,\dots,k.
			\end{aligned}

\begin{aligned}
			& \underset{\mathbf{x}}{\text{minimize}}
			& & f(\mathbf{x}) \\
			& \text{subject to}
			& & g_i(\mathbf{x})\leq \mathbf{a}_i,&\forall i=1,2,\dots,m,\\
			& & & h_j(\mathbf{x})=\mathbf{b}_j,&\forall j=1,2,\dots,k.
			\end{aligned}

\begin{aligned}
& \underset{\mathbf{x}\in{\mathbb R}^n}{\text{minimize}}
& & \|\mathbf{x}\|_1 \\
& \text{subject to}
& & A\mathbf{x}=\mathbf{b}.
\end{aligned}

\begin{aligned}
& \underset{\mathbf{v}\in{\mathbb R}^m}{\text{maximize}}
& & \mathbf{b}^{\top}\mathbf{v} \\
& \text{subject to}
& & \|A^{\top}\mathbf{v}\|_{\infty}\leq1.
\end{aligned}

We first recall the simple SNN dynamics which we call the \textit{primal SNN} from now on. For convenience, we set the threshold parameter $\eta = 1$ (and make the spiking strength parameter $\alpha$ explicit). For any $t\geq0$,
\begin{equation} \mathbf{u}(t+dt) = \mathbf{u}(t)-  \alpha \cdot A^\top A \cdot \mathbf{s}(t)+ A^\top\mathbf{b} \cdot dt.
\end{equation}

Now, we define the dual SNN $\mathbf{v}(t) \in {\mathbb R}^m$ as follows. Let $\mathbf{v}(0)=\mathbf{0}$ and for each $t\geq0$, define
\begin{equation} \mathbf{v}(t+dt) = \mathbf{v}(t) - \alpha \cdot A\mathbf{s}(t) + \mathbf{b}\cdot dt.
\end{equation}

Let $\mathcal{P}_{A,1}$ and $\mathcal{P}_{A,1-\tau}$ be defined as above. For each $\mathbf{v}^\text{ideal}\in\mathcal{P}_{A,1-\tau}$, define
	\begin{equation*}
	S_{\mathbf{v}^\text{ideal}} = \{\mathbf{v}^\text{ideal}+\mathcal{C}_{A,\Gamma(\mathbf{v}^{ideal})}\}\cap\mathcal{P}_{A,1}.
	\end{equation*}
	where $\Gamma(\mathbf{v}^\text{ideal})=\{i\in[\pm n]:\ \langle A_i,\mathbf{v}^\text{ideal}\rangle=1-\tau\}$ is the active walls of $\mathbf{v}^\text{ideal}$ and $\mathcal{C}_{A,\Gamma(\mathbf{v}^{ideal})}=\{\sum_{i\in\Gamma(\mathbf{v}^\text{ideal})}a_iA_i,\ \forall a_i\geq0\}$ is the cone spanned by the column of $A$ indexed by $\Gamma(\mathbf{v}^\text{ideal})$.

For any $t\geq0$, define the ideal solution $\mathbf{x}^\text{ideal}(t)$ at time $t$ as
	\begin{equation*}
	\mathbf{x}^\text{ideal}(t) = arg\,min_{\substack{\mathbf{x}\geq0,\\\mathbf{x}_i=0,\ \forall i\in\Gamma(\mathbf{v}^\text{ideal}(t))}}\|\mathbf{b}-A\mathbf{x}\|_2.
	\end{equation*}
	Also, let $\Gamma^*(\mathbf{v}^\text{ideal}(t))=\{i\in\Gamma(\mathbf{v}^\text{ideal}(t)):\ \mathbf{x}^\text{ideal}(t)\neq0\}$ to be the set of super active neurons.

First, note that for each $\mathbf{v}\in S_{\mathbf{v}^\text{ideal}(t)}$, by the property of dual polytope, there exists an unique $\mathbf{z}\in{\mathbb R}_{\geq0}^{|\Gamma(\mathbf{v}^\text{ideal}(t))|}$ such that $\mathbf{v}=\mathbf{v}^\text{ideal}(t)+A_{\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z}$ where $\mathbf{z}$ can be thought of as the \textit{coordinates} of $\mathbf{v}$ in $S_{\mathbf{v}^\text{ideal}(t)}$. With this concept in mind, it is then sufficient to show that whenever neuron $i$ fires, $\mathbf{z}_i>\alpha$. The reason is that
	\begin{align}
	\mathbf{v}(t)-\alpha A\mathbf{s}(t) &= \mathbf{v}^\text{ideal}(t) + A_{\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z} - \sum_{i\in\Gamma(\mathbf{v}(t))}\alpha A_i\nonumber\\
	&= \mathbf{v}^\text{ideal}(t) + \sum_{i\in\Gamma(\mathbf{v}^\text{ideal}(t))\backslash\Gamma(\mathbf{v}(t))}\mathbf{z}_iA_i + \sum_{i\in\Gamma(\mathbf{v}(t))}(\mathbf{z}_i-\alpha)A_i. \end{align}
	As a result, if $\mathbf{z}_i-\alpha>0$ for every $i\in\Gamma(\mathbf{v}(t))$, then we have $\mathbf{v}(t)-\alpha A\mathbf{s}(t)\in S_{\mathbf{v}^\text{ideal}(t)}$ because every new coordinates are still non-negative. See Figure~\ref{fig:coordinate} for an example.

	\begin{figure}[h]
		\centering
		\includegraphics[width=10cm]{pic/level.png}
		\caption{This is an example of \textit{coordinates} of  $S_{\mathbf{v}^\text{ideal}}$ in ${\mathbb R}^2$ where $\tau=0.4$, $A_1=[0\ -1]^\top$ and $A_2=[\frac{1}{\sqrt{2}}\ -\frac{1}{\sqrt{2}}]^\top$. The light gray area is the ideal polytope and the dark gray area is the dual polytope. In this example, the dot lines are the \textit{level set} of each coordinates in $S_{\mathbf{v}\text{ideal}}$. For instance, the $\mathbf{v}$ in the figure has coordinate $\mathbf{z}=[0.1\ 0.2]^\top$ and thus we have $\mathbf{v}=\mathbf{v}^\text{ideal}+A\mathbf{z}$.} \end{figure}
	\vspace{3mm}

	\begin{claim} There exists a polynomial $\alpha(\cdot)$ such that when $0<\alpha\leq{\mathrm{poly}}(\frac{\tau\cdot\gamma(A)}{n\cdot\lambda_{\max}})$ and $\mathbf{v}(t)=\mathbf{v}^\text{ideal}(t)+A_{\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z}\in S_{\mathbf{v}^\text{ideal}(t)}$ for some $t\geq0$, if $i\in\Gamma(\mathbf{v}(t))$, then $\mathbf{z}_i>\alpha$.
	\end{claim}
	\begin{proof}[Proof of Claim~\ref{claim:ideal SNN stay after fire coordinate}]
		The proof consists of two steps. First, we are going to show that for any $t\geq0$, $\mathbf{v}(t)$ is close to $\mathbf{v}^\text{ideal}(t)$. Concretely, if $\alpha\leq\frac{\tau}{m}$, then $\|\mathbf{v}(t)-\mathbf{v}^\text{ideal}(t)\|_2\leq\tau\lambda_{\max}$. Second, we are going to show that once we pick $\alpha$ small enough, then for any $i\in\Gamma(\mathbf{v}^\text{ideal}(t))$, the wall $W_i$ is far away from the $\alpha$-level set in $S_{\mathbf{v}^\text{ideal}(t)}$. Thus, whenever neuron $i$ fires, $\mathbf{z}_i>\alpha$.

		The first step is a key observation that the distance between $\mathbf{v}(t)$ and $\mathbf{v}^\text{ideal}(t)$ would not increase after the neurons fire spikes. The main reason is that neuron $i$ fires at time $t$ if and only if $A_i^\top\mathbf{v}(t)>1$. As a result,
		\begin{align*}
		\|\left(\mathbf{v}(t)-\alpha A\mathbf{s}(t)\right)-\mathbf{v}^\text{ideal}(t)\|_2^2 &= \|\mathbf{v}(t)-\mathbf{v}^\text{ideal}(t)\|_2^2 + \alpha^2\|A\mathbf{s}(t)\|_2^2 - 2\alpha\left(A\mathbf{s}(t)\right)^\top\left(\mathbf{v}(t)-\mathbf{v}^\text{ideal}(t)\right)\\
		& = \|\mathbf{v}(t)-\mathbf{v}^\text{ideal}(t)\|_2^2 + \alpha^2\|A\mathbf{s}(t)\|_2^2 -2\alpha\sum_{i\in\Gamma(\mathbf{v}(t))}A_i^\top\left(\mathbf{v}(t)-\mathbf{v}^\text{ideal}(t)\right)\\
		&\leq\|\mathbf{v}(t)-\mathbf{v}^\text{ideal}(t)\|_2^2 + \alpha^2|\Gamma(\mathbf{v}(t))|^2 -2\alpha\tau|\Gamma(\mathbf{v}(t))|.
		\end{align*}
		That is, if $\alpha\leq\frac{\tau}{m}$, then $\|\left(\mathbf{v}(t)-\alpha A\mathbf{s}(t)\right)-\mathbf{v}^\text{ideal}(t)\|_2$ would not increase after some neurons fire. Furthermore, the longest distance between $\mathbf{v}(t)$ and $\mathbf{v}^\text{ideal}(t)$ would then be $\tau\lambda_{\max}$.

		The second step is rather complicated. Let us start with some definitions. Recall that for any $i\in[\pm n]$, the wall $i$ is defined as $W_i=\{\mathbf{v}\in{\mathbb R}^m:\ A_i^\top\mathbf{v}=1 \}$. Now, define the $\alpha$-level set of $i$ in $S_{\mathbf{v}^\text{ideal}(t)}$ as
		$$
		L_{\mathbf{v}^\text{ideal}(t),i,\alpha} = \{\mathbf{v}\in S_{\mathbf{v}^\text{ideal}(t)}:\ \mathbf{v}=\mathbf{v}^\text{ideal}(t)+A_{\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z},\ \mathbf{z}_i=\alpha\}. 
		$$
		That is, $L_{\mathbf{v}^\text{ideal}(t),i,\alpha} $ consists of the set of points in $S_{\mathbf{v}^\text{ideal}(t)}$ that has the $i^\text{th}$ coordinate to be $\alpha$.

		\begin{claim}[furtherest point in $S_{\mathbf{v}^\text{ideal}}$] For any $t\geq0$, let $\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}$ be the unique point $\mathbf{v}\in S_{\mathbf{v}^\text{ideal}(t)}$ such that for any $i\in\Gamma(\mathbf{v}^\text{ideal}(t))$, $A_i^\top\left(\mathbf{v}-\mathbf{v}^\text{ideal}(t)\right)=\tau$. Then, we have $\|\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}-\mathbf{v}^\text{ideal}(t)\|_2=\max_{\mathbf{v}\in S_{\mathbf{v}^\text{ideal}(t)}}\|\mathbf{v}-\mathbf{v}^\text{ideal}(t)\|_2$.
		\end{claim}
		\begin{proof}[Proof of Claim~\ref{claim:furthest point in safe region}]
			Let us prove by contradiction. Suppose $\mathbf{v}^*\in S_{\mathbf{v}^\text{ideal}(t)}$ such that $\|\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}-\mathbf{v}^\text{ideal}(t)\|_2<\|\mathbf{v}^*-\mathbf{v}^\text{ideal}(t)\|_2$. To simplify the notations, let $\mathbf{v}_{\Gamma}=\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}-\mathbf{v}^\text{ideal}(t)$ and $\mathbf{v}=\mathbf{v}^*-\mathbf{v}^\text{ideal}(t)$.

			By definition, we have $A_i^\top\mathbf{v}_\Gamma=\tau$ for all $i\in\Gamma(\mathbf{v}^\text{ideal}(t))$ and $\mathbf{v}=A_{\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z}_\Gamma$ for some $\mathbf{z}_\Gamma\in{\mathbb R}_{>0}$. On the other hand, we also have $0\leq A_i^\top\mathbf{v}\leq\tau$ for all $i\in\Gamma(\mathbf{v}^\text{ideal}(t)$.

			Now, look at the quantity $\mathbf{v}_{\Gamma}^\top\left(\mathbf{v}-\mathbf{v}_\Gamma\right)$. Note that since $\|\mathbf{v}\|_2>\|\mathbf{v}_\Gamma\|_2$, we have $\mathbf{v}_{\Gamma}^\top\left(\mathbf{v}-\mathbf{v}_\Gamma\right)>0$. Also, for any $i\in\Gamma(\mathbf{v}^\text{ideal}(t))$, we have $A_i^\top\left(\mathbf{v}-\mathbf{v}_\Gamma\right)\leq0$. Using the fact that $\mathbf{v}=A_{\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z}_\Gamma$ for some $\mathbf{z}_\Gamma\in{\mathbb R}_{>0}$, we have
			\begin{align*}
			0 < \mathbf{v}_{\Gamma}^\top\left(\mathbf{v}-\mathbf{v}_\Gamma\right)&=\mathbf{z}_\Gamma^\top A_{\Gamma(\mathbf{v}^\text{ideal}(t))}^\top\left(\mathbf{v}-\mathbf{v}_\Gamma\right)\\
			&= \mathbf{z}_\Gamma^\top\mathbf{u}\leq0,
			\end{align*}
			where $\mathbf{u}=A_{\Gamma(\mathbf{v}^\text{ideal}(t))}^\top\left(\mathbf{v}-\mathbf{v}_\Gamma\right)\in{\mathbb R}_{\leq0}^{|\Gamma(\mathbf{v}^\text{ideal}(t))|}$. That is, we reach a contradiction and thus $\|\mathbf{v}\|_2\leq\|\mathbf{v}_\Gamma\|_2$ and we conclude that $\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}$ is the furtherest point from $\mathbf{v}^\text{ideal}(t)$ in $S_{\mathbf{v}^\text{ideal}(t)}$.
		\end{proof}
		\begin{claim}[intersection of wall and $\alpha$-level set is far] When $0<\alpha\leq\tau^2\cdot\gamma(A)^3$, for any $t\geq0$ and $i\in\Gamma(\mathbf{v}^\text{ideal}(t))$, we have
			$$
			\min_{\mathbf{v}:\ \mathbf{v}\in W_i\cap L_{\mathbf{v}^\text{ideal}(t),i,\alpha}}\|\mathbf{v}-\mathbf{v}^\text{ideal}(t)\|_2>\|\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}-\mathbf{v}^\text{ideal}(t)\|_2.
			$$
		\end{claim}
		\begin{proof}[Proof of Claim~\ref{claim:ideal SNN intersection is far}]
			First, let us write $\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}=\mathbf{v}^\text{ideal}(t)+\sum_{i\in\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z}_iA_i$ where $\mathbf{z}_i\geq\tau\cdot\gamma(A)$ by Definition~\ref{def:nice}. Furthermore, for any $i\in\Gamma(\mathbf{v}^\text{ideal}(t))$, we have
			\begin{equation*}
			\text{dist}\left(\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))},\text{span}(A_{\Gamma(\mathbf{v}^\text{ideal}(t))\backslash\{i\}})\right)\geq|\mathbf{z}_i|\cdot\text{dist}\left(A_i,\text{span}(A_{\Gamma(\mathbf{v}^\text{ideal}(t))\backslash\{i\}})\right)\geq\tau\cdot\gamma(A)^2,
			\end{equation*}
			where the last inequality follows Definition~\ref{def:nice}. Namely, if we pick $0<\alpha<\tau^2\cdot\gamma(A)^3$, then
			\begin{equation*}
			\text{dist}\left(\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))},L_{\mathbf{v}^\text{ideal}(t),i,\alpha}\right)>0
			\end{equation*}
			and $\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}\in\text{Cone}(A_i,L_{\mathbf{v}^\text{ideal}(t),i,\alpha})$ because $\mathbf{z}_i\geq\gamma(A)$. Finally, observe that for any $\mathbf{v}\in W_i\cap L_{\mathbf{v}^\text{ideal}(t),i,\alpha}$, we have $\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}^\top\left(\mathbf{v}-\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}\right)>0$. This completes the proof of Claim~\ref{claim:ideal SNN intersection is far}.
		\end{proof}
		Combine Claim~\ref{claim:furthest point in safe region} and Claim~\ref{claim:ideal SNN intersection is far}, we know that when neuron $i$ fires, the corresponding coordinate $\mathbf{z}_i$ will be at least $\alpha$. This completes the proof of Claim~\ref{claim:ideal SNN stay after fire coordinate}.
	\end{proof}
	Now, Lemma~\ref{lem:ideal SNN unchaged} follows from Claim~\ref{claim:ideal SNN stay after fire coordinate} and equation~\eqref{eq:ideal SNN fire}.

The reason is that
	\begin{align}
	\mathbf{v}(t)-\alpha A\mathbf{s}(t) &= \mathbf{v}^\text{ideal}(t) + A_{\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z} - \sum_{i\in\Gamma(\mathbf{v}(t))}\alpha A_i\nonumber\\
	&= \mathbf{v}^\text{ideal}(t) + \sum_{i\in\Gamma(\mathbf{v}^\text{ideal}(t))\backslash\Gamma(\mathbf{v}(t))}\mathbf{z}_iA_i + \sum_{i\in\Gamma(\mathbf{v}(t))}(\mathbf{z}_i-\alpha)A_i. \end{align}
