	\end{equation*}
	Here, $\mathbf{x}^+$ is the optimal solution of~\eqref{op:quadratic program proof} and we let $\mathbf{b}^+=A\mathbf{x}^+$ which is the conic projection of $\mathbf{b}$ on the cone spanned by the column of $A$.

Note that $\mathbf{x}^+$ is also the optimal solution of the following optimization program with minimum value to be $0$.
	\begin{equation} \min_{\mathbf{x}}\|A\mathbf{x}-\mathbf{b}^+\|_2^2.
	\end{equation}

Given a simple SNN with $C=A^\top A$ and $\mathbf{I}=A^\top\mathbf{b}$, the dual SNN as defined in Section~\ref{sec:dual SNN} would be
	\begin{equation*}
	\mathbf{v}(t) = t\cdot\left(\mathbf{b}-A\mathbf{x}(t)\right).
	\end{equation*}
	Define $\mathbf{v}^+(t)=\mathbf{v}(t)-t\cdot\left(\mathbf{b}-\mathbf{b}^+\right)=t\cdot\left(\mathbf{b}^+-A\mathbf{x}(t)\right)$.

Let us start with an observation on Definition~\ref{def:ideal partition} about the points on the boundary of  the ideal polytope $\mathcal{P}_{A,1-\tau}$.
	\begin{claim} If $A$ is non-degenerate, then for any $\mathbf{v}^\text{ideal}\in\partial\mathcal{P}_{A,1-\tau}$, $\text{rank}(A_{\Gamma(\mathbf{v}^\text{ideal})})=|\Gamma(\mathbf{v}^\text{ideal})|$. Thus, $A_{\Gamma(\mathbf{v}^\text{ideal})}^\top A_{\Gamma(\mathbf{v}^\text{ideal})}$ is positive definite.
	\end{claim}

	Next, let us show that for $\mathbf{v}^\text{ideal}_1\neq\mathbf{v}^\text{ideal}_2\in\mathcal{P}_{A,1-\tau}$, $S_{\mathbf{v}^\text{ideal}_1}\cap S_{\mathbf{v}^\text{ideal}_2}=\emptyset$. It is trivially true when at least one of them does not lie on the boundary\footnote{Note that $\mathbf{v}^\text{ideal}$ does not lie on the boundary of $\mathcal{P}_{A,1-\tau}$ if and only if $\Gamma(\mathbf{v}^\text{ideal})=\emptyset$.} of $\mathcal{P}_{A,1-\tau}$. Now, consider the case where both of them lie on the boundary of $\mathcal{P}_{A,1-\tau}$ and denote their active set as $\Gamma_1=\Gamma(\mathbf{v}^\textit{ideal}_1)$ and $\Gamma_2=\Gamma(\mathbf{v}^\textit{ideal}_2)$. To prove from contradiction, suppose there exists $\mathbf{v}\in S_{\mathbf{v}^\text{ideal}_1}\cap S_{\mathbf{v}^\text{ideal}_2}$. By definition, we have
	\begin{align*}
	\mathbf{v} &= \mathbf{v}^\text{ideal}_1 + A_{\Gamma_1}^\top\mathbf{z}_1\\
	&=\mathbf{v}^\text{ideal}_2 + A_{\Gamma_2}^\top\mathbf{z}_2,
	\end{align*}
	where $\mathbf{z}_1,\mathbf{z}_2\geq0$. Let $\Gamma=\Gamma_1\cap\Gamma_2$. Consider the following cases.
	\begin{itemize}
		\item ($\Gamma=\Gamma_1=\Gamma_2$) By Definition~\ref{def:ideal partition}, we have $A_\Gamma^\top\mathbf{v}^\text{ideal}_1=A_\Gamma^\top\mathbf{v}^\text{ideal}_2=\mathbf{1}$ and thus
		\begin{equation*}
		(\mathbf{z}_2-\mathbf{z}_1)^\top A_\Gamma^\top A_\Gamma(\mathbf{z}_2-\mathbf{z}_1)=(\mathbf{z}_2-\mathbf{z}_1)^\top A_\Gamma^\top(\mathbf{v}^\text{ideal}_1-\mathbf{v}^\text{ideal}_2)=0.
		\end{equation*}
		As $A_\Gamma^\top A_\Gamma$ is positive definite by Claim~\ref{claim:ideal active PD}, we have $\mathbf{z}_1=\mathbf{z}_2$ and $\mathbf{v}^\text{ideal}_1=\mathbf{v}^\text{ideal}_2$, which is a contradiction.

		\item ($\Gamma_1\neq\Gamma_2$) Without loss of generality, assume $\Gamma_1\backslash\Gamma\neq\emptyset$ and $\mathbf{z}_1\neq\mathbf{0}$. By Definition~\ref{def:ideal partition}, we have
		\begin{align*}
		A_{\Gamma_1\backslash\Gamma_2}^\top\left(\mathbf{v}^\text{ideal}_1-\mathbf{v}^\text{ideal}_2\right)&>\mathbf{0},\\
		A_{\Gamma_2\backslash\Gamma_1}^\top\left(\mathbf{v}^\text{ideal}_1-\mathbf{v}^\text{ideal}_2\right)&\leq\mathbf{0},\\
		A_{\Gamma}^\top\left(\mathbf{v}^\text{ideal}_1-\mathbf{v}^\text{ideal}_2\right)&=\mathbf{0}.
		\end{align*}
		As $\mathbf{z}_1\neq\mathbf{0}$, we then have
		\begin{align*}
		\|A_{\Gamma_2}\mathbf{z}_2-A_{\Gamma_1}\mathbf{z}_1\|_2^2 &= \left(A_{\Gamma_2}\mathbf{z}_2-A_{\Gamma_1}\mathbf{z}_1\right)^\top\left(\mathbf{v}^\text{ideal}_1-\mathbf{v}^\text{ideal}_2\right)\\
		&=\left(-A_{\Gamma_1\backslash\Gamma}\mathbf{z}_1|_{\Gamma_1\backslash\Gamma}\right)^\top\left(\mathbf{v}^\text{ideal}_1-\mathbf{v}^\text{ideal}_2\right)\\
		&+\left(A_{\Gamma_2\backslash\Gamma}\mathbf{z}_2|_{\Gamma_2\backslash\Gamma}\right)^\top\left(\mathbf{v}^\text{ideal}_1-\mathbf{v}^\text{ideal}_2\right)\\
		&+\left(A_{\Gamma}\mathbf{z}_2|_{\Gamma}-A_{\Gamma}\mathbf{z}_1|_{\Gamma}\right)^\top\left(\mathbf{v}^\text{ideal}_1-\mathbf{v}^\text{ideal}_2\right)\\
		&<0.
		\end{align*}
		Note that the reason why the last inequality holds is because $\left(-A_{\Gamma_1\backslash\Gamma}\mathbf{z}_1|_{\Gamma_1\backslash\Gamma}\right)^\top\left(\mathbf{v}^\text{ideal}_1-\mathbf{v}^\text{ideal}_2\right)<0$.
	\end{itemize}
	Finally, it is easy to see that $\{S_{\mathbf{v}^\text{ideal}}\}_{\mathbf{v}^\text{ideal}\in\mathcal{P}_{A,1-\tau}}$ covers $\mathcal{P}_{A,1}$ and thus we conclude that it is indeed a partition for $\mathcal{P}_{A,1}$.

