{Lemma~\ref{lemma:idealalgorithm-OPTbounds}}
	For any $t\geq0$, define the following perturbed program of (\ref{op:basispursuit}) and its dual.
	\vspace{3mm}
	\begin{minipage}{\linewidth}
		\begin{minipage}{0.45\linewidth}
			\begin{equation} \begin{aligned}
			& \underset{\mathbf{x}}{\text{minimize}}
			& & \|\mathbf{x}\|_1 \\
			& \text{subject to}
			& & A\mathbf{x}-A\mathbf{x}^{\text{ideal}}(t)=0
			\end{aligned}
			\end{equation}
		\end{minipage}
		\begin{minipage}{0.45\linewidth}
			\begin{equation} \begin{aligned}
			& \underset{\mathbf{v}\in{\mathbb R}^m}{\text{maximize}}
			& & (A\mathbf{x}^{\text{ideal}}(t))\top\mathbf{v} \\
			& \text{subject to}
			& & \|A^\top\mathbf{v}\|_{\infty}\leq1.
			\end{aligned}
			\end{equation}
		\end{minipage}
	\end{minipage}

	Note that $\mathbf{x}^{\text{ideal}}(t)$ is treated as a given constant to the optimization program. It turns out that the ideal algorithm optimizes this primal-dual perturbed program at time $t$ with the following parameters.
	\begin{lemma} For any $t\geq0$, $(\mathbf{x}^*,\mathbf{v}^*) = (\mathbf{x}^{\text{ideal}}(t),\mathbf{v}^{\text{ideal}}(t))$ is the optimal solutions of (\ref{op:basispursuit-ideal-perturbed}).
	\end{lemma}
	\begin{proof}{Proof of Lemma~\ref{lemma:proofofidealalgorithm-KKT}}
		We simply check the KKT condition. Since the program can be rewritten as a linear program, it satisfies the regularity condition of the KKT condition.

		First, the primal and the dual feasibility can be verified by the dynamics of ideal algorithm. That is, $A\mathbf{x}^*-A\mathbf{x}^{\text{ideal}}(t)=0$ and $\|A^\top\mathbf{v}^*\|_{\infty}\leq1$. Next, consider the Lagrangian of~\eqref{op:basispursuit-ideal-perturbed} as follows.
		\begin{align*}
		\mathcal{L}(\mathbf{x},\mathbf{v}) &= \|\mathbf{x}\|_1 - \mathbf{v}^\top (A\mathbf{x}-A\mathbf{x}^{\text{ideal}}(t)),\\
		\nabla_{\mathbf{x}}\mathcal{L}(\mathbf{x},\mathbf{v}) &= \nabla\|\mathbf{x}\|_1-A^\top \mathbf{v}.
		\end{align*}
		Now, let's verify that the gradient of the Lagrangian over $\mathbf{x}$ is vanishing at $(\mathbf{x}^*,\mathbf{v}^*) = (\mathbf{x}^{\text{ideal}}(t),\mathbf{v}^{\text{ideal}}(t))$. That is,  $0\in\nabla_{\mathbf{x}}\mathcal{L}(\mathbf{x}^*,\mathbf{v}^*)=\nabla\|\mathbf{x}\|_1-A^\top \mathbf{v}$. Consider two cases as follows. For any $i\in[n]$,
		\begin{enumerate}[label=(\arabic*)]
			\item When $i,-i\notin\Gamma^{\text{ideal}}(t)$. We have $\Big(\mathbf{x}^{\text{ideal}}(t) \Big)_i=0$, {\it i.e.,\ } the sub-gradient of the $i$th coordinate of $\|\mathbf{x}^{\text{ideal}}(t)\|_1$ lies in $[-1,1]$. As $A_i\top\mathbf{v}^{\text{ideal}}(t)\in[-1,1]$, we have $A_i\top\mathbf{v}^{\text{ideal}}(t)\in\partial_{\mathbf{x}_i}\|\mathbf{x}^{\text{ideal}}(t)\|_1$.
			\item When $i\in\Gamma^{\text{ideal}}(t)$ (or $-i\in\Gamma^{\text{ideal}}(t)$). We have $A_i\top\mathbf{v}^{\text{ideal}}(t)=1$ (or $A_i\top\mathbf{v}^{\text{ideal}}(t)=-1$). As $\text{sgn}\Big(\mathbf{x}^{\text{ideal}}(t) \Big)_i=1$ (or $\text{sgn}\Big(\mathbf{x}^{\text{ideal}}(t) \Big)_i=-1$), we have $A_i\top\mathbf{v}^{\text{ideal}}(t)=\text{sgn}\Big(\mathbf{x}^{\text{ideal}}(t) \Big)_i=\partial_{\mathbf{x}_i}\|\mathbf{x}^{\text{ideal}}(t)\|_1$.
		\end{enumerate}
		Finally, the complementary slackness is satisfied because $A\mathbf{x}^*-A\mathbf{x}^{\text{ideal}}(t)=0$.
		As a result, we conclude that $(\mathbf{x}^*,\mathbf{v}^*)$ is the optimal solution of (\ref{op:basispursuit-ideal-perturbed}).
	\end{proof}

	Next, we are going to use the perturbation lemma in the Chapter 5.6 of~\cite{boyd2004convex} stated as follows.

	\begin{lemma}[perturbation lemma]
		Given the following two optimization programs.\\
		\begin{minipage}{\linewidth}
			\begin{minipage}{0.45\linewidth}
				\begin{equation} \begin{aligned}
				& \underset{\mathbf{x}}{\text{minimize}}
				& & f(\mathbf{x}) \\
				& \text{subject to}
				& & h(\mathbf{x})=\mathbf{0}.
				\end{aligned}
				\end{equation}
			\end{minipage}
			\begin{minipage}{0.45\linewidth}
				\begin{equation} \begin{aligned}
				& \underset{\mathbf{x}}{\text{minimize}}
				& & f(\mathbf{x}) \\
				& \text{subject to}
				& & h(\mathbf{x})=\mathbf{y}.
				\end{aligned}
				\end{equation}
			\end{minipage}
		\end{minipage}
		Let $\mathbf{OPT}^{\text{original}}$ be the optimal value of the original program~\eqref{op:perturbation-original} and $\mathbf{OPT}^{\text{perturbed}}$ be the optimal value of the perturbed program~\eqref{op:perturbation-perturbed}. Let $\mathbf{v}^*$ be the optimal dual value of the perturbed program~\eqref{op:perturbation-perturbed}. We have
		\begin{equation}
		\mathbf{OPT}^{\text{original}}\geq\mathbf{OPT}^{\text{perturbed}}+\mathbf{y}^\top\mathbf{v}^*.
		\end{equation}
	\end{lemma}

	Now, think of~\eqref{op:basispursuit} as the original program and~\eqref{op:basispursuit-ideal-perturbed} as the perturbed program. Namely, $f(\mathbf{x})=\|\mathbf{x}\|_1$, $h(\mathbf{x})=A\mathbf{x}-\mathbf{b}$, and $\mathbf{y}=A\mathbf{x}^{\text{ideal}}(t)-\mathbf{b}$. By the perturbation lemma, we have
	\begin{align*}
	\mathbf{OPT}^{\ell_1}&\geq \|\mathbf{x}^{\text{ideal}}(t)\|_1 +  \Big(A\mathbf{x}^{\text{ideal}}(t)-\mathbf{b}\Big)^\top\mathbf{v}^{\text{ideal}}(t).
	\end{align*}
	As a result, the following upper bound holds.
	\begin{equation} \|\mathbf{x}^{\text{ideal}}(t)\|_1\leq\mathbf{OPT}^{\ell_1} + \|\mathbf{v}^{\text{ideal}}(t)\|_2\cdot\|\mathbf{b}-A\mathbf{x}^{\text{ideal}}(t)\|_2.
	\end{equation}
	Finally, as $\mathbf{v}^{\text{ideal}}(t)$ lies in the feasible region $\{\mathbf{v}:\ A^\top \mathbf{v}\|_{\infty}\leq1 \}$ and the range space of $A$, we can upper bound the $\|\mathbf{v}^{\text{ideal}}(t)\|_2$ term in~\eqref{eq:proofofidealalgorithm-1} as follows.
	\begin{lemma} For any $\mathbf{v}$ in the range space of $A$ and $\|A^\top \mathbf{v}\|_{\infty}\leq1$, $\|\mathbf{v}\|_2\leq\sqrt{\frac{n}{\lambda_{\min}}}$.
	\end{lemma}
	\begin{proof}{Proof of Lemma~\ref{lemma:proofofidealalgorithm-vbound}}
		As $\mathbf{v}$ lies in the range space of $A$, we have $\|A^\top\mathbf{v}\|_2\geq\sqrt{\lambda_{\min}}\|\mathbf{v}\|_2$. Also, because $\|A^\top\mathbf{v}\|_{\infty}\leq1$, we have $\|A^\top\mathbf{v}\|_2\leq\sqrt{n}$. As a result, 
		\begin{equation*}
		\|\mathbf{v}\|_2\leq\frac{\|A^\top\mathbf{v}\|_2}{\sqrt{\lambda_{\min}}}\leq\sqrt{\frac{n}{\lambda_{\min}}}.
		\end{equation*}
	\end{proof}
	By~\eqref{eq:proofofidealalgorithm-1} and Lemma~\ref{lemma:proofofidealalgorithm-vbound}, Lemma~\ref{lemma:idealalgorithm-OPTbounds} holds.

